func _run_tests() -> void:
	var head_file := FileAccess.open("res://.git/HEAD", FileAccess.READ)
	if not check("git_head", head_file != null, "L'archivio Git deve essere presente"):
		return

	var log_file := FileAccess.open("res://.git/logs/HEAD", FileAccess.READ)
	if not check("git_log", log_file != null, "Il file di registro .git/logs/HEAD deve esistere"):
		return

	var content: String = log_file.get_as_text()
	var lines: PackedStringArray = content.split("\n", false)
	var commit_messages: Array[String] = []

	for line in lines:
		var commit_idx: int = line.find("commit")
		if commit_idx != -1:
			var msg_part: String = line.substr(commit_idx)
			var colon_idx: int = msg_part.find(":")
			if colon_idx != -1:
				msg_part = msg_part.substr(colon_idx + 1)
			var cleaned: String = msg_part.strip_edges()
			if not cleaned.is_empty():
				commit_messages.append(cleaned)

	var count: int = commit_messages.size()
	if not check("commit_count", count >= 5, "La storia di Git deve contenere almeno 5 commit (trovati: %d)" % count):
		return

	var all_long_enough: bool = true
	var unique_messages: Dictionary = {}
	for msg in commit_messages:
		unique_messages[msg] = true
		if msg.length() < 10:
			all_long_enough = false

	check("commit_len", all_long_enough, "Tutti i messaggi dei commit devono essere descrittivi (almeno 10 caratteri)")
	check("commit_unique", unique_messages.size() >= 5, "I messaggi dei commit devono essere tutti distinti tra loro")
